# -*- coding: utf-8 -*-
# Сверка с ответами учебника Алимов 9, часть 2 (расхождения 70–134): пересчитано вручную + SymPy (check_al2.py), условия сверены со сканом.
KB = "ключ неверен (сверка с ответом учебника Алимов 9 и пересчёт вручную): "
SRC = "сверка с ответами учебника Алимов 9 25.09 + пересчёт вручную"
P = {}
def K(t, k, note, **kw):
    P[t] = {"k": k, "why": KB + note, "src": SRC}; P[t].update(kw)
OLD = lambda v, n: [(v, "прежний (неверный) ключ: " + n)]
K("G9_TB_13_155_2", r"$(17; 10)$, $(4; -3)$", "x = y + 7 ⇒ y² − 7y − 30 = 0 ⇒ y = 10 или −3 (было (9; 2), (2; −5): 81 − 18 − 4 ≠ 19)")
K("G9_TB_13_157_1", r"$(4{,}5; -2{,}5)$", "x + y = 14/7 = 2, x − y = 7 ⇒ x = 4,5, y = −2,5 (было (4; −3): 16 − 9 ≠ 14)")
K("G9_TB_ТЗГ5_3", r"уменьшится на $\dfrac{1}{45}$", "15/27 = 5/9 → 16/30 = 8/15, 8/15 − 5/9 = −1/45 (было «увеличится»)", dadd=OLD(r"увеличится на $\dfrac{1}{45}$", "неверный знак изменения"))
K("G9_TB_2_4_4", r"$1$", "5x² − 4x − 1 = 0 ⇒ x = 1 или −1/5; из чисел −2; 0; 1; √3 нулём является только 1 (в ключе было −1/5, которого нет в списке)")
K("G9_TB_32_407_2", r"$b_{5}=4802$, $S_{4}=800$ или $b_{5}=-4802$, $S_{4}=600$", "q² = 686/14 = 49 ⇒ q = 7, b₁ = 2 или q = −7, b₁ = −2 (второй случай был потерян)")
K("G9_TB_33_413_4", r"Да, является: $q^{4} = \dfrac{b_{9}}{b_{5}} = \dfrac{1}{243}$, поэтому $|q| = \dfrac{1}{\sqrt[4]{243}} < 1$.", "q⁴ = (−1/27)/(−9) = 1/243, а не 1/81 — в ключе было неверное обоснование q = ±1/3 (вывод «да» верен)")
K("G9_TB_ПовтКурс_548_2", r"$\sin\alpha = \dfrac{120}{169}$, $\cos\alpha = \dfrac{119}{169}$", "cos(α/2) = −12/13: sin α = 2·(−5/13)(−12/13) = 120/169, cos α = 1 − 2·25/169 = 119/169 (было −119/169)",
  dadd=OLD(r"$\sin\alpha = \dfrac{120}{169}$, $\cos\alpha = \dfrac{-119}{169}$", "ошибка в знаке cos α"))
